'use client';

import React, { useState } from 'react';
// import { addQuestion } from '../../lib/actions/questions';
import Input from '../Input/input';
import Button from '../Button/button';
import styles from './questionsForm.module.css';

function QuestionsForm({ action, editedQuestionId, questions }) {
    const [editedQuestion, setEditedQuestion] = useState(null);

    if(editedQuestionId) {
        const question = questions.find((question) => question.id === editedQuestionId);
        setEditedQuestion(question);
    }

    return (
        <form action={action} className={styles.newQuestion}>
            <Input 
                name='question' 
                label={'Pytanie'}
                defaultValue={editedQuestion ? editedQuestion.question : ''}
                required
            />
            <Input 
                name='answer' 
                label={'Odpowiedź'}
                defaultValue={editedQuestion ? editedQuestion.answer : ''}
                required
            />
            <Button type='submit' text={'Dodaj'}/>
        </form>
    );
}

export default QuestionsForm;